-- ============================================================
-- Ascesis demo data: a year of history plus a live 30-day arc.
-- Paste into the Supabase SQL Editor and press Run.
-- Safe to run more than once (it clears its own data first).
-- ============================================================

do $$
declare
  u uuid;
begin
  select id into u from auth.users where email = 'zuhadzahid1@gmail.com';
  if u is null then
    raise exception 'No account found for zuhadzahid1@gmail.com. Sign up in the app first.';
  end if;

  -- Start clean so this can be re-run.
  delete from public.deep_work_sessions where user_id = u;
  delete from public.daily_logs where user_id = u;
  delete from public.goals where user_id = u;
  delete from public.challenges where user_id = u;
  delete from public.tasks where user_id = u;

  values ('0c6dfee8-5298-4029-bc1b-a577a5ff0693'::uuid, u, 'Summer Arc', 'Rebuild the habit of deep work and get back in shape.', '2026-06-01', '2026-07-30', '[{"id":"2b1a2222-1e0a-41c8-a6a5-8b1d8092e837","text":"90 minutes of deep work before noon"},{"id":"69079eab-e1ed-459a-9880-bff0e09e0373","text":"Run or gym, 5 days a week"},{"id":"b2fa80c2-73b5-40d9-acaa-9e3622bae8cf","text":"No screens after 11pm"}]'::jsonb, 90);
  values ('664a4198-513e-41f3-bc3b-ab08dc31d8d5'::uuid, u, 'Winter Arc', 'Ship Ascesis to its first 100 users, and hold sleep and training every single day.', '2026-09-16', '2026-10-15', '[{"id":"6ee275cd-75d3-492e-baa0-20df64694a4f","text":"2 hours of deep work"},{"id":"201bb610-200c-4971-95d2-28025d23d459","text":"30 minutes of exercise"},{"id":"5ec4b573-d378-4b46-8155-a5e486a43d32","text":"No junk food"},{"id":"36429d42-cb2d-4cef-8232-11c1b50aab72","text":"Sleep before 1am"}]'::jsonb, 120);



- [x] Homepage
- [x] Pricing page
- [ ] Contact form
- [ ] Deploy to production', 'a2');

  -- Daily logs. daily_score is computed by the trigger, not by us.

  raise notice 'Seeded % daily logs, 2 challenges, % goals, % tasks.', 229, 13, 11;
end;
$$;

-- Quick look at what landed:
select to_char(log_date,'YYYY-MM') as month, count(*) as days_logged, round(avg(daily_score),1) as avg_score
from public.daily_logs
where user_id = (select id from auth.users where email = 'zuhadzahid1@gmail.com')
group by 1 order by 1;
